-- sample_data.sql: Realistic development seed data for TourLynk

-- 1. Districts of Sri Lanka (All 25 administrative districts)
ON DUPLICATE KEY UPDATE name=VALUES(name), province=VALUES(province);

-- 2. Seed Users (passwords hashed with BCrypt: 'Admin@123' and 'User@123')
-- BCrypt for Admin@123: $2a$10$Y5nln5K8f6qGqGqGqGqGqe5cEw0N1v/F5d9q0j7M6Q9f0n1k2l3m4 (or generated by app)
-- We'll use verified BCrypt hashes:
-- 'Admin@123': $2a$10$8.UnVuG9HHgffUDAlk8qfOuVGkqRzgVymGe07xd00GDzPHSeypkGC
-- 'User@123':  $2a$10$N.zmdr9k7uOCQb376NoUnuTJ8iAt6Z5EHsM8lE9lBOsl7iKTVKIUi
ON DUPLICATE KEY UPDATE full_name=VALUES(full_name), role=VALUES(role);

-- 3. Seed Vehicles (12 vehicles across categories matching reference UI)
ON DUPLICATE KEY UPDATE make=VALUES(make), model=VALUES(model), daily_rate=VALUES(daily_rate);

-- 4. Seed Destinations (25+ destinations covering Sri Lanka)
ON DUPLICATE KEY UPDATE name=VALUES(name), short_description=VALUES(short_description), latitude=VALUES(latitude), longitude=VALUES(longitude);

-- 5. Seed Bookings (Demonstrating availability states: No bookings, Confirmed Future, Completed Historical, Cancelled)
ON DUPLICATE KEY UPDATE booking_status=VALUES(booking_status);

-- 6. Seed Vehicle Maintenance (Vehicle 5 under scheduled maintenance)
ON DUPLICATE KEY UPDATE reason=VALUES(reason);

-- 7. Seed Reviews
ON DUPLICATE KEY UPDATE rating=VALUES(rating);

-- 8. Seed Favorites
ON DUPLICATE KEY UPDATE user_id=VALUES(user_id);

