INSERT INTO vehicles (id, make, model, manufacturing_year, category, description, registration_number, passenger_capacity, luggage_capacity, transmission, fuel_type, daily_rate, listing_status, primary_image_url) VALUES
(1, 'Toyota', 'Axio', 2022, 'Car', 'A comfortable and fuel-efficient premium sedan suited for city driving and long-distance Sri Lankan highway touring.', 'WP-CAB-1024', 5, 2, 'Auto', 'Hybrid', 8000.00, 'AVAILABLE', '/assets/images/vehicles/toyota-axio.jpg'),
(2, 'Toyota', 'RAV4', 2023, 'SUV', 'Versatile all-wheel-drive crossover SUV offering supreme comfort, spacious interior, and reliable clearance for mountain roads.', 'WP-CAG-4482', 5, 3, 'Auto', 'Petrol', 18000.00, 'AVAILABLE', '/assets/images/vehicles/toyota-rav4.jpg'),
(3, 'Toyota', 'HiAce', 2021, 'Van', 'Spacious high-roof luxury passenger van, ideal for family holidays, tourist groups, and luggage-heavy Sri Lankan tours.', 'WP-NA-7821', 12, 6, 'Auto', 'Diesel', 25000.00, 'AVAILABLE', '/assets/images/vehicles/toyota-hiace.jpg'),
(4, 'Toyota', 'Prado', 2023, 'SUV', 'Flagship luxury 4x4 Land Cruiser Prado combining legendary off-road capability with executive comfort across all terrains.', 'WP-CBA-9011', 7, 4, 'Auto', 'Diesel', 28000.00, 'AVAILABLE', '/assets/images/vehicles/toyota-prado.jpg'),
(5, 'Toyota', 'Prius', 2022, 'Car', 'Ultra-efficient hybrid hatchback with smooth highway performance and cutting-edge safety features for eco-conscious travelers.', 'WP-CAC-5590', 5, 3, 'Auto', 'Hybrid', 10500.00, 'AVAILABLE', '/assets/images/vehicles/toyota-prius.jpg'),
(6, 'Toyota', 'Aqua', 2021, 'Compact', 'Nimble and highly economical compact car, perfect for navigating narrow Sri Lankan coastal lanes and historic town streets.', 'WP-CAD-3120', 5, 2, 'Auto', 'Hybrid', 7500.00, 'AVAILABLE', '/assets/images/vehicles/toyota-aqua.jpg'),
(7, 'Nissan', 'X-Trail', 2022, 'SUV', 'Modern family SUV equipped with intelligent 4x4 drive, panoramic moonroof, and generous boot space for adventure trips.', 'WP-CAE-8901', 5, 4, 'Auto', 'Petrol', 16500.00, 'AVAILABLE', '/assets/images/vehicles/nissan-xtrail.jpg'),
(8, 'Honda', 'Vezel', 2023, 'SUV', 'Sleek urban crossover featuring dynamic hybrid power, ergonomic interior styling, and flexible magic seating arrangements.', 'WP-CAF-6211', 5, 3, 'Auto', 'Hybrid', 14000.00, 'AVAILABLE', '/assets/images/vehicles/honda-vezel.jpg'),
(9, 'Suzuki', 'Wagon R', 2021, 'Compact', 'Compact tall-boy wagon designed for effortless parking, superior fuel economy, and great headroom on island getaways.', 'WP-CAH-1194', 4, 2, 'Auto', 'Petrol', 6500.00, 'AVAILABLE', '/assets/images/vehicles/suzuki-wagonr.jpg'),
(10, 'Nissan', 'Caravan', 2020, 'Van', 'Robust 14-seater touring van tailored for organized group excursions, airport transfers, and hill country round-trips.', 'WP-NB-3420', 14, 8, 'Auto', 'Diesel', 24000.00, 'AVAILABLE', '/assets/images/vehicles/nissan-caravan.jpg'),
(11, 'Mitsubishi', 'Montero Sport', 2023, 'SUV', 'Muscular 7-seater SUV with high ground clearance, paddle shift transmission, and commanding road presence on highland slopes.', 'WP-CBI-7342', 7, 5, 'Auto', 'Diesel', 32000.00, 'AVAILABLE', '/assets/images/vehicles/mitsubishi-montero.jpg'),
(12, 'Mercedes-Benz', 'E-Class', 2022, 'Luxury', 'Prestige executive luxury saloon offering peerless ride refinement, plush leather upholstery, and VIP hospitality standards.', 'WP-CBK-9900', 5, 3, 'Auto', 'Petrol', 45000.00, 'AVAILABLE', '/assets/images/vehicles/mercedes-eclass.jpg')
INSERT INTO destinations (id, name, slug, district, province, short_description, full_description, latitude, longitude, category, best_visit_period, estimated_visit_duration, entrance_fee_information, primary_image_url, average_rating, review_count, is_active) VALUES
(1, 'Sigiriya Rock Fortress', 'sigiriya-rock-fortress', 'Matale', 'Central', 'An ancient palace and fortress complex atop a sheer 200m granite monolith, renowned for frescoes and water gardens.', 'Sigiriya is a UNESCO World Heritage site and an ancient rock fortress located in the northern Matale District near the town of Dambulla in the Central Province, Sri Lanka. It is a site of historical and archaeological significance dominated by a massive column of rock nearly 200 metres high. According to the ancient Sri Lankan chronicle the Culavamsa, this site was selected by King Kashyapa for his new capital.', 7.9570, 80.7603, 'Cultural', 'January to April', '3 - 4 hours', 'USD 30 (Foreigners) / LKR 100 (Locals)', '/assets/images/destinations/sigiriya.jpg', 4.8, 1240, TRUE),
(2, 'Ella Nine Arch Bridge', 'ella-nine-arch-bridge', 'Badulla', 'Uva', 'Iconic colonial railway viaduct hidden amidst lush jungle hills and emerald tea plantations near Ella.', 'The Nine Arch Bridge in Ella is one of the best examples of colonial-era railway construction in the country. Built entirely out of solid rock, bricks, and cement without a single piece of steel, the bridge stands 24 meters high and spans 91 meters across a picturesque ravine surrounded by rolling hills and dense green tea bushes. Visitors love catching the scenic blue train crossing the bridge.', 6.8768, 81.0608, 'Nature', 'December to May', '2 hours', 'Free admission', '/assets/images/destinations/nine-arch-bridge.jpg', 4.7, 980, TRUE),
(3, 'Galle Fort', 'galle-fort', 'Galle', 'Southern', 'A vibrant 17th-century seaside fortress built by the Portuguese and Dutch, featuring quaint cobblestone streets and cafes.', 'Galle Fort, in the Bay of Galle on the southwest coast of Sri Lanka, was built first in 1588 by the Portuguese, then extensively fortified by the Dutch during the 17th century from 1649 onwards. It is a historical, archaeological and architectural heritage monument, which even after more than 400 years maintains a polished appearance, boasting boutique hotels, museums, gem shops, and panoramic sea ramparts.', 6.0270, 80.2170, 'Cultural', 'November to April', 'Half day', 'Free admission (Museums extra)', '/assets/images/destinations/galle-fort.jpg', 4.6, 1120, TRUE),
(4, 'Yala National Park', 'yala-national-park', 'Hambantota', 'Southern', 'Sri Lanka’s premier wildlife park, boasting the world’s highest density of wild leopards and thriving elephant herds.', 'Yala National Park is the most visited and second largest national park in Sri Lanka. Bordering the Indian Ocean, the park consists of five blocks and encompasses a variety of ecosystems ranging from moist monsoon forests to freshwater and marine wetlands. It is renowned for having one of the highest leopard densities in the world, alongside sloth bears, saltwater crocodiles, and hundreds of bird species.', 6.3686, 81.5278, 'Wildlife', 'February to July', 'Full day safari', 'USD 40 + Jeep Hire', '/assets/images/destinations/yala.jpg', 4.5, 880, TRUE),
(5, 'Anuradhapura Sacred City', 'anuradhapura-sacred-city', 'Anuradhapura', 'North Central', 'Cradle of ancient Sri Lankan civilization with sprawling monasteries, soaring stupas, and the sacred Sri Maha Bodhi tree.', 'Anuradhapura was the first capital of Sri Lanka established in the 4th century BC. The sacred city features monumental dagobas like Ruwanwelisaya and Jetavanaramaya, intricate stone carvings, and the revered Jaya Sri Maha Bodhi, the oldest surviving historically recorded human-planted tree in the world.', 8.3500, 80.4167, 'Cultural', 'Year-round (dry season preferred)', 'Full day', 'USD 25 (Foreigners)', '/assets/images/destinations/anuradhapura.jpg', 4.7, 650, TRUE),
(6, 'Temple of the Sacred Tooth Relic', 'temple-of-the-tooth-kandy', 'Kandy', 'Central', 'A revered Buddhist temple situated in the royal palace complex of the former Kingdom of Kandy, housing Buddha’s tooth.', 'Sri Dalada Maligawa or the Temple of the Sacred Tooth Relic is a Buddhist temple in the city of Kandy, Sri Lanka. It is located in the royal palace complex of the former Kingdom of Kandy, which houses the relic of the tooth of the Buddha. Since ancient times, the relic has played an important role in local politics because it is believed that whoever holds the relic holds the governance of the country.', 7.2936, 80.6413, 'Cultural', 'Year-round', '2 - 3 hours', 'USD 15 / LKR 2000 (Foreigners)', '/assets/images/destinations/kandy-temple.jpg', 4.8, 1430, TRUE),
(7, 'Nuwara Eliya & Gregory Lake', 'nuwara-eliya-gregory-lake', 'Nuwara Eliya', 'Central', 'Known as Little England, characterized by cool mountain climate, colonial bungalows, tea estates, and misty lakes.', 'Nuwara Eliya is a city in the hill country of the Central Province, Sri Lanka. Its name means "city on the plain" or "city of light". The city is the administrative capital of Nuwara Eliya District, with a picturesque landscape and temperate climate. It is at an altitude of 1,868 m and is considered to be the most important location for tea production in Sri Lanka.', 6.9538, 80.7818, 'Nature', 'March to June', '1 - 2 days', 'Free admission (Lake park nominal fee)', '/assets/images/destinations/nuwara-eliya.jpg', 4.6, 910, TRUE),
(8, 'Mirissa Beach & Whale Watching', 'mirissa-beach', 'Matara', 'Southern', 'Crescent-shaped golden beach famous for blue whale watching excursions, vibrant sunsets, and relaxed seaside seafood dining.', 'Mirissa is a small town on the south coast of Sri Lanka. Mirissa’s beach and nightlife make it a popular tourist destination. It is also a fishing port and one of the island’s main whale and dolphin watching locations, where majestic blue whales migrate between the Arabian Sea and the Bay of Bengal.', 5.9483, 80.4589, 'Coastal', 'November to April', '1 - 2 days', 'Free beach access', '/assets/images/destinations/mirissa.jpg', 4.7, 1050, TRUE),
(9, 'Polonnaruwa Ancient City', 'polonnaruwa-ancient-city', 'Polonnaruwa', 'North Central', 'The medieval second capital of Sri Lanka, showcasing marvels of irrigation and magnificent rock-cut statues at Gal Vihara.', 'Polonnaruwa was the thriving medieval capital of Sri Lanka from the 11th to 13th centuries. Renowned for its green environment, ancient artificial reservoirs like Parakrama Samudra, and the sublime rock-cut Buddha statues of Gal Vihara carved into granite.', 7.9403, 81.0188, 'Cultural', 'May to September', 'Half day', 'USD 25', '/assets/images/destinations/polonnaruwa.jpg', 4.6, 520, TRUE),
(10, 'Horton Plains & World’s End', 'horton-plains-worlds-end', 'Nuwara Eliya', 'Central', 'A windswept cloud forest plateau with breathtaking 880m sheer precipices and crystal-clear Baker’s Falls.', 'Horton Plains National Park is a protected area in the central highlands of Sri Lanka covered by montane grassland and cloud forest. World’s End is a sheer cliff with an 870 m (2,854 ft) drop that offers mesmerizing panoramic views across tea valleys to the southern coastline on clear mornings.', 6.8028, 80.8092, 'Nature', 'January to March', '4 hours', 'USD 35', '/assets/images/destinations/horton-plains.jpg', 4.7, 740, TRUE),
(11, 'Dambulla Cave Temple', 'dambulla-cave-temple', 'Matale', 'Central', 'The largest and best-preserved cave temple complex in Sri Lanka, boasting 153 Buddha statues and stunning mural ceilings.', 'Also known as the Golden Temple of Dambulla, this World Heritage site is an extraordinarily well-preserved cave monastery dating back to the first century BC. Five separate caverns contain hundreds of statues and vibrant Buddhist mural paintings spanning 2,100 square meters.', 7.8567, 80.6489, 'Cultural', 'Year-round', '2 hours', 'USD 10', '/assets/images/destinations/dambulla.jpg', 4.7, 830, TRUE),
(12, 'Unawatuna Beach', 'unawatuna-beach', 'Galle', 'Southern', 'A calm horseshoe-shaped turquoise bay protected by coral reefs, ideal for swimming, snorkeling, and beachfront relaxation.', 'Unawatuna is a coastal town in Galle district of Sri Lanka. Known for its tranquil sandy beach, family-safe calm waters, water sports, and beachside restaurants offering fresh grilled seafood under the stars.', 6.0108, 80.2492, 'Coastal', 'November to April', '1 day', 'Free admission', '/assets/images/destinations/unawatuna.jpg', 4.5, 690, TRUE),
(13, 'Udawalawe National Park', 'udawalawe-national-park', 'Monaragala', 'Uva', 'Expansive savannah grasslands surrounding a massive reservoir, famous for guaranteed encounters with wild elephant families.', 'Udawalawe National Park lies on the boundary of Sabaragamuwa and Uva Provinces. It was created to provide a sanctuary for wild animals displaced by the construction of the Udawalawe Reservoir and is home to hundreds of wild Sri Lankan elephants and the famous Elephant Transit Home.', 6.4744, 80.8986, 'Wildlife', 'October to April', 'Half day safari', 'USD 25 + Jeep Hire', '/assets/images/destinations/udawalawe.jpg', 4.6, 610, TRUE),
(14, 'Arugam Bay Surf Haven', 'arugam-bay', 'Ampara', 'Eastern', 'World-class right-hand point break surf destination celebrated for its bohemian vibe, lagoons, and golden sandbars.', 'Arugam Bay is a historic settlement of the ancient Batticaloa territory and a world-renowned surf spot located on the Indian Ocean in the dry zone of Sri Lanka’s southeast coast. Surfers from around the globe flock here between May and September.', 6.8419, 81.8344, 'Coastal', 'May to September', '2 - 3 days', 'Free beach access', '/assets/images/destinations/arugam-bay.jpg', 4.7, 820, TRUE),
(15, 'Trincomalee & Koneswaram Temple', 'trincomalee-koneswaram', 'Trincomalee', 'Eastern', 'Ancient cliffside Hindu temple dedicated to Lord Shiva, overlooking the natural deep-water harbour and Swami Rock.', 'Koneswaram Temple is a classical-medieval Hindu temple complex in Trincomalee, perched atop Swami Rock surrounded by the sea. Trincomalee is blessed with powder-soft white sand beaches, maritime history, and crystal-clear snorkeling coves.', 8.5878, 81.2417, 'Cultural', 'March to October', 'Half day', 'Free admission', '/assets/images/destinations/trincomalee.jpg', 4.6, 590, TRUE),
(16, 'Nilaveli Beach & Pigeon Island', 'nilaveli-pigeon-island', 'Trincomalee', 'Eastern', 'Pristine white sand coastline and marine national park harboring live coral reefs, blacktip reef sharks, and sea turtles.', 'Nilaveli is a beach resort town located 16 km northwest of Trincomalee. Just offshore lies Pigeon Island National Park, which contains some of the best remaining coral reefs of Sri Lanka, offering world-class snorkeling with docile reef sharks and turtles.', 8.6883, 81.1897, 'Coastal', 'April to October', '1 day', 'National Park entry fee applies', '/assets/images/destinations/nilaveli.jpg', 4.8, 770, TRUE),
(17, 'Jaffna Fort & Nallur Temple', 'jaffna-fort-nallur', 'Jaffna', 'Northern', 'The cultural epicentre of Tamil heritage in Sri Lanka, boasting Dutch-era bastions, golden Hindu towers, and unique cuisine.', 'Jaffna Fort is a large coastal fort built by the Portuguese in 1618 and later expanded by the Dutch. Nearby stands the resplendent Nallur Kandaswamy Kovil, one of the most sacred Hindu pilgrimage sites in Sri Lanka.', 9.6615, 80.0094, 'Cultural', 'January to September', '1 - 2 days', 'Free admission', '/assets/images/destinations/jaffna.jpg', 4.5, 430, TRUE),
(18, 'Adam’s Peak (Sri Pada)', 'adams-peak-sri-pada', 'Ratnapura', 'Sabaragamuwa', 'Sacred 2,243m conical mountain climbed by pilgrims of four religions for its sacred footprint and mystical sunrise shadow.', 'Adam’s Peak is a tall conical mountain located in central Sri Lanka. It is well known for the Sri Pada, i.e., "sacred footprint", a 1.8 m rock formation near the summit. The night climb up thousands of illuminated stone steps culminates in a glorious sunrise.', 6.8096, 80.4994, 'Adventure', 'December to May', '6 - 8 hours climb', 'Free admission', '/assets/images/destinations/adams-peak.jpg', 4.9, 1310, TRUE),
(19, 'Bentota Beach & Watersports', 'bentota-beach', 'Galle', 'Southern', 'Golden sandy peninsula flanked by the Indian Ocean and Bentota River, offering jet skiing, windsurfing, and luxury resorts.', 'Bentota is a coastal town in Sri Lanka, located in the Southern Province. Facing the Indian Ocean, a tropical lagoon and a river, Bentota offers some of the best water sports, river cruises through mangrove forests, and sea turtle hatcheries.', 6.4256, 79.9997, 'Coastal', 'October to April', '1 day', 'Free beach access', '/assets/images/destinations/bentota.jpg', 4.6, 680, TRUE),
(20, 'Hikkaduwa Coral Sanctuary', 'hikkaduwa-coral-sanctuary', 'Galle', 'Southern', 'Celebrated marine reserve renowned for sea turtle feeding on the beach shore, colorful coral reefs, and vibrant surf breaks.', 'Hikkaduwa is a seaside resort town located in southwestern Sri Lanka. Its beach and nightlife make it an iconic tourist destination. It is home to a shallow fringing coral reef where giant green turtles regularly swim up to the shore to feed.', 6.1408, 80.1017, 'Coastal', 'November to April', '1 day', 'Free beach access', '/assets/images/destinations/hikkaduwa.jpg', 4.5, 750, TRUE),
(21, 'Sinharaja Rain Forest Reserve', 'sinharaja-rain-forest', 'Ratnapura', 'Sabaragamuwa', 'A virgin tropical rainforest UNESCO biosphere reserve home to over 50% of Sri Lanka’s endemic mammals, birds, and flora.', 'Sinharaja Forest Reserve is a national park and a biodiversity hotspot in Sri Lanka. It is of international significance and has been designated a Biosphere Reserve and World Heritage Site by UNESCO. It represents the last viable area of primary tropical rainforest on the island.', 6.4167, 80.4667, 'Nature', 'December to April, August', 'Half to full day', 'USD 10 + Guide fee', '/assets/images/destinations/sinharaja.jpg', 4.7, 510, TRUE),
(22, 'Pinnawala Elephant Orphanage', 'pinnawala-elephant-orphanage', 'Kegalle', 'Sabaragamuwa', 'A conservation center caring for orphaned and injured wild Asian elephants, famous for twice-daily river bathing spectacles.', 'Pinnawala Elephant Orphanage is an orphanage, nursery, and captive breeding ground for wild Asian elephants located at Pinnawala village in Kegalle District. Visitors gather on riverbank terraces to watch entire elephant herds bathe and play in the Maha Oya river.', 7.3009, 80.3867, 'Wildlife', 'Year-round', '3 hours', 'USD 20 (Foreigners)', '/assets/images/destinations/pinnawala.jpg', 4.4, 890, TRUE),
(23, 'Colombo Lotus Tower & City', 'colombo-lotus-tower', 'Colombo', 'Western', 'South Asia’s tallest self-supported tower offering 360-degree observation decks over Colombo harbour and skyline.', 'The Colombo Lotus Tower is a 350-meter-tall telecommunications and observation landmark in Colombo, Sri Lanka. The flower-shaped crown features observation decks, revolving dining, and luminous night illumination facing the Indian Ocean.', 6.9271, 79.8612, 'Cultural', 'Year-round', '2 hours', 'USD 20 / LKR 500 (Foreign/Local)', '/assets/images/destinations/colombo.jpg', 4.5, 940, TRUE),
(24, 'Negombo Lagoon & Fish Market', 'negombo-lagoon', 'Gampaha', 'Western', 'Charming coastal fishing hub near Bandaranaike Airport, noted for colorful outrigger catamarans and Dutch colonial canals.', 'Negombo is a major city in Sri Lanka, situated on the western coast at the mouth of the Negombo Lagoon. Known for its centuries-old fishing industry, bustling beachside open-air fish markets, Dutch canal cruises, and close proximity to the airport.', 7.2083, 79.8358, 'Coastal', 'November to April', 'Half day', 'Free admission', '/assets/images/destinations/negombo.jpg', 4.4, 490, TRUE),
(25, 'Wilpattu National Park', 'wilpattu-national-park', 'Puttalam', 'North Western', 'Sri Lanka’s largest national park, characterized by over 100 natural sand-rimmed water basins (willus) and solitary leopards.', 'Wilpattu National Park is located in the lowland dry zone of the northwest coast of Sri Lanka. What makes this park unique is the existence of "Willus" – natural, sand-rimmed water basins that fill with rainwater and attract deer, wild boar, sloth bears, and leopards.', 8.4550, 80.0028, 'Wildlife', 'February to October', 'Full day safari', 'USD 30 + Jeep hire', '/assets/images/destinations/wilpattu.jpg', 4.6, 420, TRUE)
