INSERT INTO reviews (id, user_id, destination_id, vehicle_id, rating, review_text) VALUES
(1, 2, 1, NULL, 5, 'Climbing Sigiriya at sunrise was the highlight of our trip! The ancient hydraulic gardens and frescoes are breathtaking.'),
(2, 3, 2, NULL, 5, 'Watching the blue train cross the Nine Arch Bridge surrounded by misty tea plantations was truly unforgettable.'),
(3, 2, 3, NULL, 4, 'Loved walking along the historic Galle ramparts at sunset. Great boutique cafes inside the fort.'),
(4, 3, NULL, 2, 5, 'The Toyota RAV4 handled the steep hills of Nuwara Eliya with absolute ease. Very smooth drive and spotless interior!')
